script:
frappe.ui.form.on('Daily Trip Log', {
  log_date: function(frm){ set_day_type(frm); set_month(frm); calc_rate(frm); },
  employee: function(frm){ setTimeout(function(){ set_group_unit(frm); calc_rate(frm); }, 700); },
  pay_group: function(frm){ set_unit(frm); calc_rate(frm); },
  branch: function(frm){ calc_rate(frm); },
  quantity: function(frm){ calc_rate(frm); }
});

var GROUP_UNIT = {
  'Mixer Driver':'Trip','Pump Driver':'Trip','Trailer Driver':'Trip',
  'Pump Operator':'Cubic','Plant Operator':'Cubic','Chemical':'Fixed'
};

function set_day_type(frm){
  if(!frm.doc.log_date) return;
  var d = frappe.datetime.str_to_obj(frm.doc.log_date);
  frm.set_value('day_type', (d.getDay()===6) ? 'Saturday' : 'Weekday');
}
function set_month(frm){
  if(frm.doc.log_date){ frm.set_value('payroll_month', frm.doc.log_date.substring(0,7)); }
}
function set_group_unit(frm){
  var desig = frm.doc.designation;
  if(desig && GROUP_UNIT.hasOwnProperty(desig)){ frm.set_value('pay_group', desig); }
  set_unit(frm);
}
function set_unit(frm){
  var g = frm.doc.pay_group;
  if(g && GROUP_UNIT[g]){ frm.set_value('unit', GROUP_UNIT[g]); }
}
function calc_rate(frm){
  if(!frm.doc.pay_group || !frm.doc.log_date || !frm.doc.day_type){ return; }
  var site = frm.doc.branch || 'All';
  frappe.call({
    method:'frappe.client.get_list',
    args:{
      doctype:'BGL Trip Rate',
      filters:[['pay_group','=',frm.doc.pay_group],['day_type','=',frm.doc.day_type],['is_active','=',1],['effective_from','<=',frm.doc.log_date],['site','in',[site,'All']]],
      fields:['rate','site','effective_from','salary_component'],
      order_by:'effective_from desc',
      limit_page_length:20
    },
    callback:function(r){
      var rows=(r.message)||[];
      if(!rows.length){ frm.set_value('rate_applied',0); frm.set_value('amount',0); frm.set_value('salary_component','');
        frm.dashboard.set_headline('No active rate found for '+frm.doc.pay_group+' / '+site+' / '+frm.doc.day_type+' - add it in BGL Trip Rate.'); return; }
      rows.sort(function(a,b){ var sa=(a.site===site)?0:1, sb=(b.site===site)?0:1; if(sa!==sb) return sa-sb; return (a.effective_from<b.effective_from)?1:-1; });
      var chosen=rows[0];
      frm.set_value('rate_applied',chosen.rate||0);
      frm.set_value('amount',(frm.doc.quantity||0)*(chosen.rate||0));
      if(chosen.salary_component){ frm.set_value('salary_component', chosen.salary_component); }
      frm.dashboard.clear_headline();
    }
  });
}

frappe.ui.form.on('Staff Loan Advance', {
  refresh: function(frm){ recompute(frm); },
  validate: function(frm){ recompute(frm); },
  principal: function(frm){ recompute(frm); }
});
frappe.ui.form.on('Staff Loan Repayment', {
  amount: function(frm){ recompute(frm); },
  repayments_remove: function(frm){ recompute(frm); }
});
function recompute(frm){
  var t=0;
  (frm.doc.repayments||[]).forEach(function(r){ t+=(r.amount||0); });
  frm.set_value('total_repaid', t);
  var bal=(frm.doc.principal||0)-t;
  frm.set_value('balance', bal);
  if(frm.doc.status!=='Written Off' && frm.doc.status!=='Cancelled'){
    frm.set_value('status', (bal<=0.001) ? 'Fully Paid' : 'Active');
  }
}

frappe.ui.form.on('Take Home Planner', {
  refresh: function(frm) {
    if (frm.is_new()) return;

    frm.add_custom_button(__('Calculate'), function() {
      frappe.call({
        method: 'thp_calculate',
        args: { docname: frm.doc.name },
        freeze: true,
        freeze_message: __('Solving gross from take home...'),
        callback: function(r) {
          if (!r.message) return;
          var m = r.message;
          frm.reload_doc();
          var msg = 'Gross <b>' + format_currency(m.gross) + '</b><br>'
            + 'Basic paid ' + format_currency(m.basic_paid) + ' (full month ' + format_currency(m.full_month_basic) + ')<br>'
            + 'Allowances ' + format_currency(m.allowances) + '<br>'
            + 'SSNIT ' + format_currency(m.ssnit) + ' &nbsp; PAYE ' + format_currency(m.paye) + '<br>'
            + 'Net <b>' + format_currency(m.net) + '</b> (variance ' + format_currency(m.variance) + ')';
          if (m.percent_total != 100) {
            msg += '<br><span style="color:#c00">Percentages total ' + m.percent_total + '%, not 100%</span>';
          }
          frappe.msgprint({ title: __('Calculated'), message: msg, indicator: 'blue' });
        }
      });
    }).addClass('btn-primary');

    if (frm.doc.status !== 'Draft') {
      frm.add_custom_button(__('Preview Changes (Dry Run)'), function() {
        frappe.call({
          method: 'thp_apply',
          args: { docname: frm.doc.name, dry_run: '1' },
          freeze: true,
          freeze_message: __('Checking what would change...'),
          callback: function(r) {
            if (!r.message) return;
            frm.reload_doc();
            frappe.msgprint({
              title: __('Dry Run - nothing written'),
              message: '<pre style="white-space:pre-wrap">' + frappe.utils.escape_html(r.message.log.join('\n')) + '</pre>',
              indicator: 'orange'
            });
          }
        });
      }, __('Apply'));

      frm.add_custom_button(__('Apply to ERPNext'), function() {
        frappe.confirm(
          __('This will create or amend the Salary Structure Assignment and Additional Salary records for {0}. Continue?', [frm.doc.employee_name]),
          function() {
            frappe.call({
              method: 'thp_apply',
              args: { docname: frm.doc.name, dry_run: '0' },
              freeze: true,
              freeze_message: __('Writing to ERPNext...'),
              callback: function(r) {
                if (!r.message) return;
                frm.reload_doc();
                frappe.msgprint({
                  title: __('Applied'),
                  message: '<pre style="white-space:pre-wrap">' + frappe.utils.escape_html(r.message.log.join('\n')) + '</pre>',
                  indicator: 'green'
                });
              }
            });
          }
        );
      }, __('Apply'));
    }

    if (frm.doc.status === 'Applied') {
      frm.dashboard.set_headline_alert(__('Applied to ERPNext on this payroll date.'), 'green');
    } else if (frm.doc.status === 'Calculated') {
      frm.dashboard.set_headline_alert(__('Calculated. Nothing written to payroll yet.'), 'orange');
    }
  }
});

frappe.ui.form.on('Take Home Bulk Run', {
  refresh: function(frm) {
    if (frm.is_new()) return;

    frm.add_custom_button(__('1. Generate Planners'), function() {
      frappe.call({
        method: 'thp_bulk_generate',
        args: { docname: frm.doc.name },
        freeze: true,
        freeze_message: __('Generating planners...'),
        callback: function(r) {
          if (!r.message) return;
          frm.reload_doc();
          frappe.msgprint({ title: __('Generated'), message: r.message.summary, indicator: 'blue' });
        }
      });
    }).addClass('btn-primary');

    if (frm.doc.status !== 'Generated') return;

    function get_planners(cb) {
      frappe.call({
        method: 'frappe.client.get_list',
        args: {
          doctype: 'Take Home Planner',
          filters: { payroll_date: frm.doc.payroll_date },
          fields: ['name'],
          limit_page_length: 0
        },
        callback: function(r) { cb((r.message || []).map(function(x){ return x.name; })); }
      });
    }

    function run_over(names, method, dry, title, done) {
      var i = 0, ok = 0, fail = 0, lines = [];
      function step() {
        if (i >= names.length) {
          frappe.hide_progress();
          frappe.msgprint({
            title: title,
            message: '<b>' + ok + ' succeeded, ' + fail + ' failed</b><br><pre style="white-space:pre-wrap;max-height:400px;overflow:auto">'
              + frappe.utils.escape_html(lines.join('\n')) + '</pre>',
            indicator: fail ? 'orange' : 'green'
          });
          if (done) done();
          return;
        }
        var nm = names[i];
        frappe.show_progress(title, i + 1, names.length, nm);
        var a = { docname: nm };
        if (dry !== null) a.dry_run = dry;
        frappe.call({
          method: method,
          args: a,
          callback: function(r) {
            ok++;
            if (r.message && r.message.log) { lines.push(nm + ': ' + r.message.log.join(' | ')); }
            else if (r.message) { lines.push(nm + ': net ' + r.message.net + ' variance ' + r.message.variance); }
            i++; step();
          },
          error: function() { fail++; lines.push(nm + ': FAILED'); i++; step(); }
        });
      }
      step();
    }

    frm.add_custom_button(__('2. Calculate All'), function() {
      get_planners(function(names) {
        if (!names.length) { frappe.msgprint(__('No planners found for this payroll date.')); return; }
        run_over(names, 'thp_calculate', null, __('Calculating'));
      });
    });

    frm.add_custom_button(__('3. Preview All (Dry Run)'), function() {
      get_planners(function(names) {
        if (!names.length) { frappe.msgprint(__('No planners found for this payroll date.')); return; }
        run_over(names, 'thp_apply', '1', __('Dry run'));
      });
    }, __('Apply'));

    frm.add_custom_button(__('4. Apply All to ERPNext'), function() {
      get_planners(function(names) {
        if (!names.length) { frappe.msgprint(__('No planners found for this payroll date.')); return; }
        frappe.confirm(
          __('This will create or amend Salary Structure Assignments and Additional Salaries for {0} employees. Salary Advance, Cubic, Absent and Loans are never touched. Continue?', [names.length]),
          function() { run_over(names, 'thp_apply', '0', __('Applying')); }
        );
      });
    }, __('Apply'));

    frm.add_custom_button(__('View Planners'), function() {
      frappe.set_route('List', 'Take Home Planner', { payroll_date: frm.doc.payroll_date });
    });
  }
});
